1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1], [0, 1],
6	  [1, -1], [1, 0], [1, 1],
7	];
8	
9	function neighbors([x, y]: Cell): Cell[] {
10	  return NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
11	}
12	
13	/** Two cells are the same cell exactly when their coordinates match. */
14	function cellKey([x, y]: Cell): string {
15	  return `${x},${y}`;
16	}
17	
18	function isAlive(cell: Cell, liveKeys: Set<string>): boolean {
19	  return liveKeys.has(cellKey(cell));
20	}
21	
22	function withoutDuplicates(cells: Cell[]): Cell[] {
23	  const byKey = new Map(cells.map((cell) => [cellKey(cell), cell]));
24	  return [...byKey.values()];
25	}
26	
27	function liveNeighborCount(cell: Cell, liveKeys: Set<string>): number {
28	  return neighbors(cell).filter((neighbor) => isAlive(neighbor, liveKeys)).length;
29	}
30	
31	/**
32	 * A birth needs 3 live neighbours, so only live cells and the cells touching
33	 * them can be alive next generation.
34	 */
35	function cellsThatCouldBeAlive(liveCells: Cell[]): Cell[] {
36	  return withoutDuplicates(
37	    liveCells.flatMap((cell) => [cell, ...neighbors(cell)]),
38	  );
39	}
40	
41	function survives(neighborCount: number): boolean {
42	  return neighborCount === 2 || neighborCount === 3;
43	}
44	
45	function isBorn(neighborCount: number): boolean {
46	  return neighborCount === 3;
47	}
48	
49	export function nextGeneration(liveCells: Cell[]): Cell[] {
50	  const liveKeys = new Set(liveCells.map(cellKey));
51	  return cellsThatCouldBeAlive(liveCells).filter((cell) => {
52	    const neighborCount = liveNeighborCount(cell, liveKeys);
53	    return isAlive(cell, liveKeys) ? survives(neighborCount) : isBorn(neighborCount);
54	  });
55	}
